-- Platform-owned bilingual editorial content. Published snapshots are separate from drafts.
create table public.cms_entries(
 id uuid primary key default gen_random_uuid(),
 kind text not null check(kind in ('page','blog')),
 slug text not null check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug)<=100),
 locale text not null check(locale in ('en','hi')),
 draft jsonb not null check(jsonb_typeof(draft)='object' and length(draft->>'title') between 1 and 180 and length(coalesce(draft->>'body',''))<=30000),
 published jsonb,
 revision integer not null default 1,
 published_revision integer,
 published_at timestamptz,
 updated_at timestamptz not null default now(),
 created_at timestamptz not null default now(),
 unique(kind,slug,locale)
);
create table public.cms_history(
 id uuid primary key default gen_random_uuid(),
 entry_id uuid not null references public.cms_entries(id) on delete cascade,
 revision integer not null,
 content jsonb not null,
 action text not null,
 actor_id uuid,
 created_at timestamptz not null default now(),
 unique(entry_id,revision)
);
create index cms_history_entry_idx on public.cms_history(entry_id,created_at desc);
create table public.cms_enquiries(
 id uuid primary key default gen_random_uuid(),
 name text not null check(length(name) between 2 and 120),
 email text not null check(length(email)<=254),
 organization text not null default '' check(length(organization)<=120),
 message text not null check(length(message) between 10 and 3000),
 locale text not null check(locale in ('en','hi')),
 status text not null default 'new' check(status in ('new','read','closed')),
 policy_id uuid not null,
 policy_revision integer not null,
 consent_at timestamptz not null default now(),
 created_at timestamptz not null default now()
);
alter table public.cms_entries enable row level security;
alter table public.cms_history enable row level security;
alter table public.cms_enquiries enable row level security;
create policy cms_entries_admin on public.cms_entries for select to authenticated using(public.is_platform_admin());
create policy cms_history_admin on public.cms_history for select to authenticated using(public.is_platform_admin());
create policy cms_enquiries_admin on public.cms_enquiries for select to authenticated using(public.is_platform_admin());
revoke all on public.cms_entries,public.cms_history,public.cms_enquiries from public,anon,authenticated,service_role;
grant select on public.cms_entries,public.cms_history,public.cms_enquiries to authenticated,service_role;

create or replace function public.saas_cms_write(actor uuid,action text,p jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare entry public.cms_entries;doc jsonb;begin
 if not exists(select 1 from public.platform_admins where user_id=actor) then raise exception 'Platform administrator required.';end if;
 if action not in ('save','publish','unpublish','restore','delete') or action is null then raise exception 'Unknown CMS action.';end if;
 if p->>'id' is not null then
  select * into entry from public.cms_entries where id=(p->>'id')::uuid for update;
  if not found then raise exception 'Content not found.';end if;
  if (p->>'revision')::integer is distinct from entry.revision then raise exception 'This content changed in another session. Reload before editing.';end if;
 elsif action<>'save' then raise exception 'Choose a saved entry first.';
 end if;
 if action='save' then
  doc:=p->'draft';
  if doc is null or jsonb_typeof(doc)<>'object' or coalesce(length(doc->>'title'),0) not between 1 and 180 or coalesce(length(doc->>'body'),0)>30000 then raise exception 'Invalid document.';end if;
  if p->>'kind'='page' and p->>'slug' not in ('home','features','pricing','about','contact','faq','privacy','terms','refunds') then raise exception 'Unknown website page.';end if;
  if entry.id is null then
   insert into public.cms_entries(kind,slug,locale,draft) values(p->>'kind',p->>'slug',p->>'locale',doc) returning * into entry;
  else
   if entry.kind is distinct from p->>'kind' or entry.slug is distinct from p->>'slug' or entry.locale is distinct from p->>'locale' then raise exception 'The URL and language cannot change after creation.';end if;
   update public.cms_entries set draft=doc,revision=revision+1,updated_at=now() where id=entry.id returning * into entry;
  end if;
 elsif action='publish' then
  update public.cms_entries set published=draft,published_revision=revision+1,published_at=now(),revision=revision+1,updated_at=now() where id=entry.id returning * into entry;
 elsif action='unpublish' then
  update public.cms_entries set published=null,published_revision=null,published_at=null,revision=revision+1,updated_at=now() where id=entry.id returning * into entry;
 elsif action='restore' then
  select content into doc from public.cms_history where id=(p->>'historyId')::uuid and entry_id=entry.id;
  if not found then raise exception 'Revision not found for this entry.';end if;
  update public.cms_entries set draft=doc,revision=revision+1,updated_at=now() where id=entry.id returning * into entry;
 else
  if entry.published is not null then raise exception 'Unpublish this entry before deleting it.';end if;
  delete from public.cms_entries where id=entry.id;
 end if;
 if action<>'delete' then insert into public.cms_history(entry_id,revision,content,action,actor_id) values(entry.id,entry.revision,entry.draft,action,actor);end if;
 insert into public.audit_log(actor_id,action,details) values(actor,'cms.'||action,jsonb_build_object('entry_id',entry.id,'slug',entry.slug,'locale',entry.locale,'revision',entry.revision));
 return to_jsonb(entry);
end;$$;

create or replace function public.saas_cms_enquiry(p jsonb) returns void
language plpgsql security definer set search_path='' as $$declare policy public.cms_entries;begin
 if p->>'consent' is distinct from 'true' then raise exception 'Consent is required.';end if;
 select * into policy from public.cms_entries where id=(p->>'policyId')::uuid and kind='page' and slug='privacy' and locale=p->>'locale' and published is not null for share;
 if not found or policy.published_revision is distinct from (p->>'policyRevision')::integer then raise exception 'Privacy policy changed or is unavailable. Reload and review it before sending.';end if;
 insert into public.cms_enquiries(name,email,organization,message,locale,policy_id,policy_revision) values(p->>'name',lower(p->>'email'),coalesce(p->>'organization',''),p->>'message',p->>'locale',policy.id,policy.published_revision);
end;$$;
create or replace function public.saas_cms_enquiry_action(actor uuid,p jsonb) returns void
language plpgsql security definer set search_path='' as $$begin
 if not exists(select 1 from public.platform_admins where user_id=actor) then raise exception 'Platform administrator required.';end if;
 if p->>'action'='delete' then delete from public.cms_enquiries where id=(p->>'id')::uuid;
 elsif p->>'action' in ('read','closed') then update public.cms_enquiries set status=p->>'action' where id=(p->>'id')::uuid;
 else raise exception 'Unknown enquiry action.';end if;
 if not found then raise exception 'Enquiry not found.';end if;
 insert into public.audit_log(actor_id,action,details) values(actor,'cms.enquiry.'||(p->>'action'),jsonb_build_object('enquiry_id',p->>'id'));
end;$$;
revoke all on function public.saas_cms_write(uuid,text,jsonb),public.saas_cms_enquiry(jsonb),public.saas_cms_enquiry_action(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.saas_cms_write(uuid,text,jsonb),public.saas_cms_enquiry(jsonb),public.saas_cms_enquiry_action(uuid,jsonb) to service_role;

