insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','home','en','{"title":"A beautiful celebration.\nA beautifully run business.","summary":"From the first enquiry to the final phere, bring your halls, bookings, menus and team together in one thoughtful workspace.","body":"## Made for the way India celebrates\nA wedding is never just a date in a calendar. It is a family, a hundred little details, and a promise to make their day feel effortless. Gatherhall helps you take care of the business behind those moments.","cta_label":"Explore plans","seo_title":"A beautiful celebration. A beautifully run business. | Gatherhall","seo_description":"From the first enquiry to the final phere, bring your halls, bookings, menus and team together in one thoughtful workspace.","category":""}'::jsonb,'{"title":"A beautiful celebration.\nA beautifully run business.","summary":"From the first enquiry to the final phere, bring your halls, bookings, menus and team together in one thoughtful workspace.","body":"## Made for the way India celebrates\nA wedding is never just a date in a calendar. It is a family, a hundred little details, and a promise to make their day feel effortless. Gatherhall helps you take care of the business behind those moments.","cta_label":"Explore plans","seo_title":"A beautiful celebration. A beautifully run business. | Gatherhall","seo_description":"From the first enquiry to the final phere, bring your halls, bookings, menus and team together in one thoughtful workspace.","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','home','hi','{"title":"खूबसूरत उत्सव।\nसलीके से चलता व्यवसाय।","summary":"पहली पूछताछ से आख़िरी फेरे तक—अपने हॉल, बुकिंग, मेन्यू और टीम को एक व्यवस्थित कार्यस्थल में साथ लाएँ।","body":"## भारत के हर उत्सव के लिए\nशादी सिर्फ़ कैलेंडर की एक तारीख़ नहीं होती। यह एक परिवार, सैकड़ों छोटी तैयारियाँ और एक यादगार दिन का वादा है। Gatherhall इन पलों के पीछे आपके व्यवसाय को व्यवस्थित रखने में मदद करता है।","cta_label":"प्लान देखें","seo_title":"खूबसूरत उत्सव। सलीके से चलता व्यवसाय। | Gatherhall","seo_description":"पहली पूछताछ से आख़िरी फेरे तक—अपने हॉल, बुकिंग, मेन्यू और टीम को एक व्यवस्थित कार्यस्थल में साथ लाएँ।","category":""}'::jsonb,'{"title":"खूबसूरत उत्सव।\nसलीके से चलता व्यवसाय।","summary":"पहली पूछताछ से आख़िरी फेरे तक—अपने हॉल, बुकिंग, मेन्यू और टीम को एक व्यवस्थित कार्यस्थल में साथ लाएँ।","body":"## भारत के हर उत्सव के लिए\nशादी सिर्फ़ कैलेंडर की एक तारीख़ नहीं होती। यह एक परिवार, सैकड़ों छोटी तैयारियाँ और एक यादगार दिन का वादा है। Gatherhall इन पलों के पीछे आपके व्यवसाय को व्यवस्थित रखने में मदद करता है।","cta_label":"प्लान देखें","seo_title":"खूबसूरत उत्सव। सलीके से चलता व्यवसाय। | Gatherhall","seo_description":"पहली पूछताछ से आख़िरी फेरे तक—अपने हॉल, बुकिंग, मेन्यू और टीम को एक व्यवस्थित कार्यस्थल में साथ लाएँ।","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','features','en','{"title":"Less coordination.\nMore celebration.","summary":"Thoughtful tools for the real rhythm of an Indian wedding venue.","body":"## Every date, clearly reserved\nPlan morning, afternoon, evening and multi-day events. Duration-aware checks help prevent overlapping hall bookings.\n## Menus that match the occasion\nBuild food-menu packages, minimum guarantees and extra services. Saved bookings preserve the rates and menu details agreed with each family.\n## Payments without the guesswork\nRecord advances, track balances and print clear confirmations. Venue customer payments stay separate from your software subscription.\n## The right access for every person\nOwners, staff and clients have different permissions. Private operations notes stay with your team.","cta_label":"Explore plans","seo_title":"Less coordination. More celebration. | Gatherhall","seo_description":"Thoughtful tools for the real rhythm of an Indian wedding venue.","category":""}'::jsonb,'{"title":"Less coordination.\nMore celebration.","summary":"Thoughtful tools for the real rhythm of an Indian wedding venue.","body":"## Every date, clearly reserved\nPlan morning, afternoon, evening and multi-day events. Duration-aware checks help prevent overlapping hall bookings.\n## Menus that match the occasion\nBuild food-menu packages, minimum guarantees and extra services. Saved bookings preserve the rates and menu details agreed with each family.\n## Payments without the guesswork\nRecord advances, track balances and print clear confirmations. Venue customer payments stay separate from your software subscription.\n## The right access for every person\nOwners, staff and clients have different permissions. Private operations notes stay with your team.","cta_label":"Explore plans","seo_title":"Less coordination. More celebration. | Gatherhall","seo_description":"Thoughtful tools for the real rhythm of an Indian wedding venue.","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','features','hi','{"title":"कम भागदौड़।\nज़्यादा खुशियाँ।","summary":"भारतीय विवाह स्थलों की वास्तविक ज़रूरतों के लिए सोच-समझकर बनाए गए उपकरण।","body":"## हर तारीख़ का स्पष्ट हिसाब\nसुबह, दोपहर, शाम और कई दिनों के समारोह की योजना बनाएँ। समय के आधार पर जाँच एक ही हॉल की टकराती बुकिंग रोकने में मदद करती है।\n## हर अवसर के लिए सही मेन्यू\nखाने के पैकेज, न्यूनतम गारंटी और अतिरिक्त सेवाएँ तय करें। सहेजी गई बुकिंग में परिवार से सहमत दरें और मेन्यू सुरक्षित रहते हैं।\n## भुगतान का पूरा हिसाब\nअग्रिम राशि दर्ज करें, बकाया देखें और स्पष्ट पुष्टि प्रिंट करें। ग्राहक के भुगतान और सॉफ़्टवेयर सदस्यता अलग रहते हैं।\n## हर व्यक्ति को सही अनुमति\nमालिक, कर्मचारी और ग्राहक की अलग-अलग अनुमतियाँ हैं। आंतरिक संचालन नोट्स सिर्फ़ आपकी टीम देखती है।","cta_label":"प्लान देखें","seo_title":"कम भागदौड़। ज़्यादा खुशियाँ। | Gatherhall","seo_description":"भारतीय विवाह स्थलों की वास्तविक ज़रूरतों के लिए सोच-समझकर बनाए गए उपकरण।","category":""}'::jsonb,'{"title":"कम भागदौड़।\nज़्यादा खुशियाँ।","summary":"भारतीय विवाह स्थलों की वास्तविक ज़रूरतों के लिए सोच-समझकर बनाए गए उपकरण।","body":"## हर तारीख़ का स्पष्ट हिसाब\nसुबह, दोपहर, शाम और कई दिनों के समारोह की योजना बनाएँ। समय के आधार पर जाँच एक ही हॉल की टकराती बुकिंग रोकने में मदद करती है।\n## हर अवसर के लिए सही मेन्यू\nखाने के पैकेज, न्यूनतम गारंटी और अतिरिक्त सेवाएँ तय करें। सहेजी गई बुकिंग में परिवार से सहमत दरें और मेन्यू सुरक्षित रहते हैं।\n## भुगतान का पूरा हिसाब\nअग्रिम राशि दर्ज करें, बकाया देखें और स्पष्ट पुष्टि प्रिंट करें। ग्राहक के भुगतान और सॉफ़्टवेयर सदस्यता अलग रहते हैं।\n## हर व्यक्ति को सही अनुमति\nमालिक, कर्मचारी और ग्राहक की अलग-अलग अनुमतियाँ हैं। आंतरिक संचालन नोट्स सिर्फ़ आपकी टीम देखती है।","cta_label":"प्लान देखें","seo_title":"कम भागदौड़। ज़्यादा खुशियाँ। | Gatherhall","seo_description":"भारतीय विवाह स्थलों की वास्तविक ज़रूरतों के लिए सोच-समझकर बनाए गए उपकरण।","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','pricing','en','{"title":"One organization.\nRoom to grow.","summary":"Choose a software subscription for your organization, with hall and team limits that fit your business.","body":"## Your venues, together\nA subscription belongs to your organization, not to each individual event. Hall and active-team limits depend on the selected plan.\n## Clear boundaries\nEvent package rates and food-menu pricing are configured by you inside your workspace. These are separate from Gatherhall subscription fees.\n## An agreement that stays agreed\nYour subscribed software price and limits are saved when you register. Public catalog changes do not silently rewrite that agreement.","cta_label":"Choose your plan","seo_title":"One organization. Room to grow. | Gatherhall","seo_description":"Choose a software subscription for your organization, with hall and team limits that fit your business.","category":""}'::jsonb,'{"title":"One organization.\nRoom to grow.","summary":"Choose a software subscription for your organization, with hall and team limits that fit your business.","body":"## Your venues, together\nA subscription belongs to your organization, not to each individual event. Hall and active-team limits depend on the selected plan.\n## Clear boundaries\nEvent package rates and food-menu pricing are configured by you inside your workspace. These are separate from Gatherhall subscription fees.\n## An agreement that stays agreed\nYour subscribed software price and limits are saved when you register. Public catalog changes do not silently rewrite that agreement.","cta_label":"Choose your plan","seo_title":"One organization. Room to grow. | Gatherhall","seo_description":"Choose a software subscription for your organization, with hall and team limits that fit your business.","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','pricing','hi','{"title":"एक संस्था।\nबढ़ने की पूरी जगह।","summary":"अपने व्यवसाय के अनुरूप हॉल और टीम सीमा वाली सॉफ़्टवेयर सदस्यता चुनें।","body":"## आपके सभी हॉल, एक साथ\nसदस्यता आपकी संस्था की होती है, हर आयोजन की अलग नहीं। हॉल और सक्रिय टीम की सीमा चुने गए प्लान पर निर्भर करती है।\n## कीमतों में स्पष्टता\nसमारोह के पैकेज और मेन्यू की दरें आप अपने कार्यस्थल में तय करते हैं। ये Gatherhall सदस्यता शुल्क से अलग हैं।\n## आपकी सहमति सुरक्षित\nपंजीकरण के समय आपकी सदस्यता की कीमत और सीमाएँ सहेजी जाती हैं। सार्वजनिक प्लान बदलने से पुराना समझौता अपने-आप नहीं बदलता।","cta_label":"अपना प्लान चुनें","seo_title":"एक संस्था। बढ़ने की पूरी जगह। | Gatherhall","seo_description":"अपने व्यवसाय के अनुरूप हॉल और टीम सीमा वाली सॉफ़्टवेयर सदस्यता चुनें।","category":""}'::jsonb,'{"title":"एक संस्था।\nबढ़ने की पूरी जगह।","summary":"अपने व्यवसाय के अनुरूप हॉल और टीम सीमा वाली सॉफ़्टवेयर सदस्यता चुनें।","body":"## आपके सभी हॉल, एक साथ\nसदस्यता आपकी संस्था की होती है, हर आयोजन की अलग नहीं। हॉल और सक्रिय टीम की सीमा चुने गए प्लान पर निर्भर करती है।\n## कीमतों में स्पष्टता\nसमारोह के पैकेज और मेन्यू की दरें आप अपने कार्यस्थल में तय करते हैं। ये Gatherhall सदस्यता शुल्क से अलग हैं।\n## आपकी सहमति सुरक्षित\nपंजीकरण के समय आपकी सदस्यता की कीमत और सीमाएँ सहेजी जाती हैं। सार्वजनिक प्लान बदलने से पुराना समझौता अपने-आप नहीं बदलता।","cta_label":"अपना प्लान चुनें","seo_title":"एक संस्था। बढ़ने की पूरी जगह। | Gatherhall","seo_description":"अपने व्यवसाय के अनुरूप हॉल और टीम सीमा वाली सॉफ़्टवेयर सदस्यता चुनें।","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','about','en','{"title":"Built around people.\nMade for their big days.","summary":"A calmer way to run the spaces where families come together.","body":"## The details behind the delight\nA beautiful celebration takes much more than a beautiful hall. It takes a team that knows the plan, a menu everyone agrees on, and confidence that every booking is accounted for.\n## Indian celebrations, thoughtfully considered\nFrom haldi and mehendi to sangeet and the wedding day, our tools make room for the way celebrations unfold. We believe useful software should support your hospitality, not get in its way.\n## One private workspace\nGatherhall brings the moving parts into one organization workspace, with separate permissions and a clear record of the details you have agreed.","cta_label":"See the features","seo_title":"Built around people. Made for their big days. | Gatherhall","seo_description":"A calmer way to run the spaces where families come together.","category":""}'::jsonb,'{"title":"Built around people.\nMade for their big days.","summary":"A calmer way to run the spaces where families come together.","body":"## The details behind the delight\nA beautiful celebration takes much more than a beautiful hall. It takes a team that knows the plan, a menu everyone agrees on, and confidence that every booking is accounted for.\n## Indian celebrations, thoughtfully considered\nFrom haldi and mehendi to sangeet and the wedding day, our tools make room for the way celebrations unfold. We believe useful software should support your hospitality, not get in its way.\n## One private workspace\nGatherhall brings the moving parts into one organization workspace, with separate permissions and a clear record of the details you have agreed.","cta_label":"See the features","seo_title":"Built around people. Made for their big days. | Gatherhall","seo_description":"A calmer way to run the spaces where families come together.","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','about','hi','{"title":"लोगों को ध्यान में रखकर।\nउनके खास दिन के लिए।","summary":"उन जगहों को चलाने का एक शांत और व्यवस्थित तरीका जहाँ परिवार साथ आते हैं।","body":"## खुशी के पीछे की तैयारी\nएक खूबसूरत समारोह के लिए सिर्फ़ सुंदर हॉल काफ़ी नहीं। टीम को योजना पता हो, मेन्यू पर सहमति हो और हर बुकिंग का स्पष्ट हिसाब हो—यह भी उतना ही ज़रूरी है।\n## भारतीय उत्सवों की समझ\nहल्दी और मेहंदी से संगीत और शादी तक, हमारे उपकरण हर चरण की तैयारी में मदद करते हैं। अच्छा सॉफ़्टवेयर आपके आतिथ्य को आसान बनाए, उसमें बाधा नहीं।\n## एक निजी कार्यस्थल\nGatherhall अलग-अलग अनुमतियों और सहमत विवरणों के स्पष्ट रिकॉर्ड के साथ काम को एक संस्था के कार्यस्थल में जोड़ता है।","cta_label":"सुविधाएँ देखें","seo_title":"लोगों को ध्यान में रखकर। उनके खास दिन के लिए। | Gatherhall","seo_description":"उन जगहों को चलाने का एक शांत और व्यवस्थित तरीका जहाँ परिवार साथ आते हैं।","category":""}'::jsonb,'{"title":"लोगों को ध्यान में रखकर।\nउनके खास दिन के लिए।","summary":"उन जगहों को चलाने का एक शांत और व्यवस्थित तरीका जहाँ परिवार साथ आते हैं।","body":"## खुशी के पीछे की तैयारी\nएक खूबसूरत समारोह के लिए सिर्फ़ सुंदर हॉल काफ़ी नहीं। टीम को योजना पता हो, मेन्यू पर सहमति हो और हर बुकिंग का स्पष्ट हिसाब हो—यह भी उतना ही ज़रूरी है।\n## भारतीय उत्सवों की समझ\nहल्दी और मेहंदी से संगीत और शादी तक, हमारे उपकरण हर चरण की तैयारी में मदद करते हैं। अच्छा सॉफ़्टवेयर आपके आतिथ्य को आसान बनाए, उसमें बाधा नहीं।\n## एक निजी कार्यस्थल\nGatherhall अलग-अलग अनुमतियों और सहमत विवरणों के स्पष्ट रिकॉर्ड के साथ काम को एक संस्था के कार्यस्थल में जोड़ता है।","cta_label":"सुविधाएँ देखें","seo_title":"लोगों को ध्यान में रखकर। उनके खास दिन के लिए। | Gatherhall","seo_description":"उन जगहों को चलाने का एक शांत और व्यवस्थित तरीका जहाँ परिवार साथ आते हैं।","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','contact','en','{"title":"Let’s talk about\nyour next chapter.","summary":"Tell us about your venue business and what you would like to organize better.","body":"## A conversation, not a commitment\nAsk about organization subscriptions, hall limits or getting started. Please do not send passwords, payment-card details or guest documents.\n## Already a member?\nSign in to view your organization account and subscription status. For payment verification, keep your provider reference ready.","cta_label":"Send enquiry","seo_title":"Let’s talk about your next chapter. | Gatherhall","seo_description":"Tell us about your venue business and what you would like to organize better.","category":""}'::jsonb,'{"title":"Let’s talk about\nyour next chapter.","summary":"Tell us about your venue business and what you would like to organize better.","body":"## A conversation, not a commitment\nAsk about organization subscriptions, hall limits or getting started. Please do not send passwords, payment-card details or guest documents.\n## Already a member?\nSign in to view your organization account and subscription status. For payment verification, keep your provider reference ready.","cta_label":"Send enquiry","seo_title":"Let’s talk about your next chapter. | Gatherhall","seo_description":"Tell us about your venue business and what you would like to organize better.","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','contact','hi','{"title":"आपके अगले अध्याय\nपर बात करें।","summary":"अपने विवाह स्थल और उन कामों के बारे में बताएँ जिन्हें आप बेहतर व्यवस्थित करना चाहते हैं।","body":"## बातचीत, कोई बाध्यता नहीं\nसदस्यता, हॉल सीमा या शुरुआत के बारे में पूछें। पासवर्ड, कार्ड की जानकारी या मेहमानों के दस्तावेज़ न भेजें।\n## पहले से सदस्य हैं?\nअपनी संस्था और सदस्यता की स्थिति देखने के लिए साइन इन करें। भुगतान की जाँच के लिए प्रदाता का संदर्भ नंबर तैयार रखें।","cta_label":"पूछताछ भेजें","seo_title":"आपके अगले अध्याय पर बात करें। | Gatherhall","seo_description":"अपने विवाह स्थल और उन कामों के बारे में बताएँ जिन्हें आप बेहतर व्यवस्थित करना चाहते हैं।","category":""}'::jsonb,'{"title":"आपके अगले अध्याय\nपर बात करें।","summary":"अपने विवाह स्थल और उन कामों के बारे में बताएँ जिन्हें आप बेहतर व्यवस्थित करना चाहते हैं।","body":"## बातचीत, कोई बाध्यता नहीं\nसदस्यता, हॉल सीमा या शुरुआत के बारे में पूछें। पासवर्ड, कार्ड की जानकारी या मेहमानों के दस्तावेज़ न भेजें।\n## पहले से सदस्य हैं?\nअपनी संस्था और सदस्यता की स्थिति देखने के लिए साइन इन करें। भुगतान की जाँच के लिए प्रदाता का संदर्भ नंबर तैयार रखें।","cta_label":"पूछताछ भेजें","seo_title":"आपके अगले अध्याय पर बात करें। | Gatherhall","seo_description":"अपने विवाह स्थल और उन कामों के बारे में बताएँ जिन्हें आप बेहतर व्यवस्थित करना चाहते हैं।","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','faq','en','{"title":"A little clarity.\nA confident beginning.","summary":"Answers to the questions venue owners ask before getting started.","body":"## Is the subscription per hall?\nNo. Your organization has one software subscription. The plan determines how many halls and active team members you can add.\n## Can I use my own event pricing?\nYes. Configure your venue rental, food-menu packages and extra services inside your private workspace. Software subscription fees are separate.\n## Can my staff and clients sign in?\nYes. Create an active directory record and send an invitation. The recipient verifies their email and explicitly accepts access to your organization.\n## What happens when access expires?\nAn expired subscription makes the workspace read-only. An administrator suspension blocks workspace access and does not automatically cancel recurring billing.\n## How do trials and payments work?\nTrial availability depends on the published plan. A trial does not itself create an automatic charge. The owner separately authorizes a Razorpay subscription for paid access.\n## Can I print a booking confirmation?\nYes. Choose a full financial statement or an event-only copy. A confirmation is not a statutory tax invoice.","cta_label":"Ask a question","seo_title":"A little clarity. A confident beginning. | Gatherhall","seo_description":"Answers to the questions venue owners ask before getting started.","category":""}'::jsonb,'{"title":"A little clarity.\nA confident beginning.","summary":"Answers to the questions venue owners ask before getting started.","body":"## Is the subscription per hall?\nNo. Your organization has one software subscription. The plan determines how many halls and active team members you can add.\n## Can I use my own event pricing?\nYes. Configure your venue rental, food-menu packages and extra services inside your private workspace. Software subscription fees are separate.\n## Can my staff and clients sign in?\nYes. Create an active directory record and send an invitation. The recipient verifies their email and explicitly accepts access to your organization.\n## What happens when access expires?\nAn expired subscription makes the workspace read-only. An administrator suspension blocks workspace access and does not automatically cancel recurring billing.\n## How do trials and payments work?\nTrial availability depends on the published plan. A trial does not itself create an automatic charge. The owner separately authorizes a Razorpay subscription for paid access.\n## Can I print a booking confirmation?\nYes. Choose a full financial statement or an event-only copy. A confirmation is not a statutory tax invoice.","cta_label":"Ask a question","seo_title":"A little clarity. A confident beginning. | Gatherhall","seo_description":"Answers to the questions venue owners ask before getting started.","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','faq','hi','{"title":"थोड़ी स्पष्टता।\nभरोसे से शुरुआत।","summary":"शुरू करने से पहले विवाह स्थल मालिकों के सामान्य सवालों के जवाब।","body":"## क्या हर हॉल की अलग सदस्यता है?\nनहीं। आपकी संस्था की एक सॉफ़्टवेयर सदस्यता होती है। प्लान के अनुसार हॉल और सक्रिय टीम सदस्यों की सीमा तय होती है।\n## क्या मैं अपनी दरें तय कर सकता हूँ?\nहाँ। अपने कार्यस्थल में हॉल किराया, खाने के मेन्यू और अतिरिक्त सेवाओं की दरें तय करें। सॉफ़्टवेयर सदस्यता शुल्क अलग है।\n## क्या कर्मचारी और ग्राहक साइन इन कर सकते हैं?\nहाँ। सक्रिय रिकॉर्ड बनाकर आमंत्रण भेजें। प्राप्तकर्ता ईमेल सत्यापित करके संस्था का आमंत्रण स्वीकार करता है।\n## सदस्यता समाप्त होने पर क्या होता है?\nसमय समाप्त होने पर कार्यस्थल केवल पढ़ने योग्य होता है। प्रशासनिक निलंबन कार्यस्थल का उपयोग रोकता है, लेकिन नियमित बिलिंग अपने-आप रद्द नहीं करता।\n## ट्रायल और भुगतान कैसे काम करते हैं?\nट्रायल प्रकाशित प्लान पर निर्भर करता है। ट्रायल अपने-आप शुल्क नहीं लगाता। भुगतान वाली सदस्यता के लिए मालिक अलग से Razorpay को अनुमति देता है।\n## क्या बुकिंग पुष्टि प्रिंट कर सकते हैं?\nहाँ। पूरी वित्तीय जानकारी या सिर्फ़ आयोजन की जानकारी वाला संस्करण चुनें। पुष्टि वैधानिक टैक्स इनवॉइस नहीं है।","cta_label":"सवाल पूछें","seo_title":"थोड़ी स्पष्टता। भरोसे से शुरुआत। | Gatherhall","seo_description":"शुरू करने से पहले विवाह स्थल मालिकों के सामान्य सवालों के जवाब।","category":""}'::jsonb,'{"title":"थोड़ी स्पष्टता।\nभरोसे से शुरुआत।","summary":"शुरू करने से पहले विवाह स्थल मालिकों के सामान्य सवालों के जवाब।","body":"## क्या हर हॉल की अलग सदस्यता है?\nनहीं। आपकी संस्था की एक सॉफ़्टवेयर सदस्यता होती है। प्लान के अनुसार हॉल और सक्रिय टीम सदस्यों की सीमा तय होती है।\n## क्या मैं अपनी दरें तय कर सकता हूँ?\nहाँ। अपने कार्यस्थल में हॉल किराया, खाने के मेन्यू और अतिरिक्त सेवाओं की दरें तय करें। सॉफ़्टवेयर सदस्यता शुल्क अलग है।\n## क्या कर्मचारी और ग्राहक साइन इन कर सकते हैं?\nहाँ। सक्रिय रिकॉर्ड बनाकर आमंत्रण भेजें। प्राप्तकर्ता ईमेल सत्यापित करके संस्था का आमंत्रण स्वीकार करता है।\n## सदस्यता समाप्त होने पर क्या होता है?\nसमय समाप्त होने पर कार्यस्थल केवल पढ़ने योग्य होता है। प्रशासनिक निलंबन कार्यस्थल का उपयोग रोकता है, लेकिन नियमित बिलिंग अपने-आप रद्द नहीं करता।\n## ट्रायल और भुगतान कैसे काम करते हैं?\nट्रायल प्रकाशित प्लान पर निर्भर करता है। ट्रायल अपने-आप शुल्क नहीं लगाता। भुगतान वाली सदस्यता के लिए मालिक अलग से Razorpay को अनुमति देता है।\n## क्या बुकिंग पुष्टि प्रिंट कर सकते हैं?\nहाँ। पूरी वित्तीय जानकारी या सिर्फ़ आयोजन की जानकारी वाला संस्करण चुनें। पुष्टि वैधानिक टैक्स इनवॉइस नहीं है।","cta_label":"सवाल पूछें","seo_title":"थोड़ी स्पष्टता। भरोसे से शुरुआत। | Gatherhall","seo_description":"शुरू करने से पहले विवाह स्थल मालिकों के सामान्य सवालों के जवाब।","category":""}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','privacy','en','{"title":"Privacy policy","summary":"Operator review required before publication.","body":"## Draft — not a published policy\nReplace this template with your reviewed privacy policy before collecting real enquiries.\n## Information and purpose\nSpecify the operator’s legal identity, contact information, categories of personal data collected, purposes, processors, retention periods, security practices and applicable rights.\n## Contact requests\nExplain how submitted contact enquiries are stored, who can access them, how long they are retained and how a person may request deletion.\n## International processing and cookies\nDescribe Supabase, payment providers and hosting arrangements accurately, along with essential session cookies and any optional tracking.","cta_label":"Contact us","seo_title":"Privacy policy | Gatherhall","seo_description":"Operator review required before publication.","category":""}'::jsonb,null,null,null);
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','privacy','hi','{"title":"गोपनीयता नीति","summary":"प्रकाशन से पहले संचालक की समीक्षा ज़रूरी है।","body":"## मसौदा — प्रकाशित नीति नहीं\nवास्तविक पूछताछ स्वीकार करने से पहले इस नमूने को अपनी समीक्षा की गई गोपनीयता नीति से बदलें।\n## जानकारी और उद्देश्य\nसंचालक की कानूनी पहचान, संपर्क, एकत्रित व्यक्तिगत जानकारी, उद्देश्य, सेवा प्रदाता, संग्रह अवधि, सुरक्षा और लागू अधिकार स्पष्ट करें।\n## संपर्क अनुरोध\nपूछताछ कहाँ रखी जाती है, उसे कौन देख सकता है, कितने समय तक रखा जाता है और मिटाने का अनुरोध कैसे किया जाए—यह बताएँ।\n## कुकी और डेटा प्रसंस्करण\nSupabase, भुगतान प्रदाता, होस्टिंग और ज़रूरी सत्र कुकी के बारे में सही जानकारी दें।","cta_label":"संपर्क करें","seo_title":"गोपनीयता नीति | Gatherhall","seo_description":"प्रकाशन से पहले संचालक की समीक्षा ज़रूरी है।","category":""}'::jsonb,null,null,null);
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','terms','en','{"title":"Terms of service","summary":"Operator review required before publication.","body":"## Draft — not a contract\nReplace this template with reviewed terms for your legal entity and business model.\n## Service and responsibilities\nDefine eligibility, account security, organization roles, permitted use, support scope and service limitations.\n## Subscription agreement\nExplain billing cycles, taxes, hall limits, plan changes, termination and the distinction between subscription charges and venue customer payments.\n## Legal provisions\nHave a qualified adviser review liability, dispute resolution and jurisdiction before publication.","cta_label":"Contact us","seo_title":"Terms of service | Gatherhall","seo_description":"Operator review required before publication.","category":""}'::jsonb,null,null,null);
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','terms','hi','{"title":"सेवा की शर्तें","summary":"प्रकाशन से पहले संचालक की समीक्षा ज़रूरी है।","body":"## मसौदा — अनुबंध नहीं\nइसे अपनी कानूनी संस्था और व्यवसाय के लिए समीक्षा की गई शर्तों से बदलें।\n## सेवा और ज़िम्मेदारियाँ\nपात्रता, खाता सुरक्षा, भूमिकाएँ, उचित उपयोग, सहायता और सेवा की सीमाएँ तय करें।\n## सदस्यता समझौता\nबिलिंग चक्र, कर, हॉल सीमा, प्लान बदलाव, समाप्ति और ग्राहक भुगतान से सदस्यता शुल्क का अंतर समझाएँ।\n## कानूनी प्रावधान\nप्रकाशन से पहले दायित्व, विवाद समाधान और क्षेत्राधिकार की योग्य सलाहकार से समीक्षा कराएँ।","cta_label":"संपर्क करें","seo_title":"सेवा की शर्तें | Gatherhall","seo_description":"प्रकाशन से पहले संचालक की समीक्षा ज़रूरी है।","category":""}'::jsonb,null,null,null);
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','refunds','en','{"title":"Cancellation & refunds","summary":"Operator review required before publication.","body":"## Draft — review before taking payments\nPublish your approved cancellation and refund terms here. Do not promise automatic refunds that your operations do not support.\n## Renewal cancellation\nThe application lets an owner request end-of-cycle cancellation of an existing Razorpay subscription. Verified paid access remains through its paid-through date.\n## Refund requests\nSpecify eligibility, timelines, contact details, deductions where lawful, and how refunds are processed and communicated.","cta_label":"Contact us","seo_title":"Cancellation & refunds | Gatherhall","seo_description":"Operator review required before publication.","category":""}'::jsonb,null,null,null);
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('page','refunds','hi','{"title":"रद्दीकरण और रिफ़ंड","summary":"प्रकाशन से पहले संचालक की समीक्षा ज़रूरी है।","body":"## मसौदा — भुगतान से पहले समीक्षा करें\nयहाँ अपनी स्वीकृत रद्दीकरण और रिफ़ंड शर्तें प्रकाशित करें। ऐसी स्वचालित वापसी का वादा न करें जो आपकी प्रक्रिया में उपलब्ध न हो।\n## नवीनीकरण रद्द करना\nमालिक मौजूदा Razorpay सदस्यता के लिए चक्र के अंत में रद्दीकरण का अनुरोध कर सकता है। सत्यापित भुगतान वाली पहुँच निर्धारित अंतिम तारीख़ तक रहती है।\n## रिफ़ंड अनुरोध\nपात्रता, समयसीमा, संपर्क, लागू कटौतियाँ और रिफ़ंड की प्रक्रिया स्पष्ट करें।","cta_label":"संपर्क करें","seo_title":"रद्दीकरण और रिफ़ंड | Gatherhall","seo_description":"प्रकाशन से पहले संचालक की समीक्षा ज़रूरी है।","category":""}'::jsonb,null,null,null);
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('blog','wedding-season-checklist','en','{"title":"Before the baraat: your wedding-season checklist","summary":"A little preparation now makes room for a calmer, more confident season.","body":"## Start with your calendar\nReview every hall and reserved time window. A morning ceremony and an evening celebration need separate setup, cleaning and handover plans.\n## Confirm the agreed menu\nCheck the selected menu, guaranteed guests and any dietary notes with the family. Keep changes in the saved booking rather than scattered across messages.\n## Give your team one version of the plan\nRecord arrival times, key family contacts and private operations notes. Share an event-only confirmation with the people who do not need financial details.\n## Close the loop on payments\nRecord advances and check the remaining balance against the saved agreement. Confirm final details before the busy week begins.","cta_label":"","seo_title":"Before the baraat: your wedding-season checklist | Gatherhall","seo_description":"A little preparation now makes room for a calmer, more confident season.","category":"Operations · 5 min read"}'::jsonb,'{"title":"Before the baraat: your wedding-season checklist","summary":"A little preparation now makes room for a calmer, more confident season.","body":"## Start with your calendar\nReview every hall and reserved time window. A morning ceremony and an evening celebration need separate setup, cleaning and handover plans.\n## Confirm the agreed menu\nCheck the selected menu, guaranteed guests and any dietary notes with the family. Keep changes in the saved booking rather than scattered across messages.\n## Give your team one version of the plan\nRecord arrival times, key family contacts and private operations notes. Share an event-only confirmation with the people who do not need financial details.\n## Close the loop on payments\nRecord advances and check the remaining balance against the saved agreement. Confirm final details before the busy week begins.","cta_label":"","seo_title":"Before the baraat: your wedding-season checklist | Gatherhall","seo_description":"A little preparation now makes room for a calmer, more confident season.","category":"Operations · 5 min read"}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('blog','wedding-season-checklist','hi','{"title":"बारात आने से पहले: शादी के सीज़न की तैयारी","summary":"आज की थोड़ी तैयारी पूरे सीज़न को अधिक शांत और व्यवस्थित बना सकती है।","body":"## कैलेंडर से शुरुआत करें\nहर हॉल और आरक्षित समय की समीक्षा करें। सुबह और शाम के समारोह के बीच सजावट, सफ़ाई और ज़िम्मेदारी सौंपने का समय रखें।\n## तय मेन्यू की पुष्टि करें\nपरिवार के साथ मेन्यू, गारंटीकृत मेहमान और आहार संबंधी जानकारी जाँचें। बदलाव संदेशों में बिखेरने के बजाय बुकिंग में सहेजें।\n## टीम को एक स्पष्ट योजना दें\nआगमन का समय, परिवार के मुख्य संपर्क और आंतरिक नोट्स दर्ज करें। जिन्हें वित्तीय जानकारी नहीं चाहिए, उन्हें सिर्फ़ आयोजन वाली पुष्टि दें।\n## भुगतान का हिसाब पूरा करें\nअग्रिम राशि दर्ज करें और समझौते के अनुसार बकाया जाँचें। व्यस्त सप्ताह से पहले अंतिम जानकारी की पुष्टि करें।","cta_label":"","seo_title":"बारात आने से पहले: शादी के सीज़न की तैयारी | Gatherhall","seo_description":"आज की थोड़ी तैयारी पूरे सीज़न को अधिक शांत और व्यवस्थित बना सकती है।","category":"विवाह स्थल मार्गदर्शिका"}'::jsonb,'{"title":"बारात आने से पहले: शादी के सीज़न की तैयारी","summary":"आज की थोड़ी तैयारी पूरे सीज़न को अधिक शांत और व्यवस्थित बना सकती है।","body":"## कैलेंडर से शुरुआत करें\nहर हॉल और आरक्षित समय की समीक्षा करें। सुबह और शाम के समारोह के बीच सजावट, सफ़ाई और ज़िम्मेदारी सौंपने का समय रखें।\n## तय मेन्यू की पुष्टि करें\nपरिवार के साथ मेन्यू, गारंटीकृत मेहमान और आहार संबंधी जानकारी जाँचें। बदलाव संदेशों में बिखेरने के बजाय बुकिंग में सहेजें।\n## टीम को एक स्पष्ट योजना दें\nआगमन का समय, परिवार के मुख्य संपर्क और आंतरिक नोट्स दर्ज करें। जिन्हें वित्तीय जानकारी नहीं चाहिए, उन्हें सिर्फ़ आयोजन वाली पुष्टि दें।\n## भुगतान का हिसाब पूरा करें\nअग्रिम राशि दर्ज करें और समझौते के अनुसार बकाया जाँचें। व्यस्त सप्ताह से पहले अंतिम जानकारी की पुष्टि करें।","cta_label":"","seo_title":"बारात आने से पहले: शादी के सीज़न की तैयारी | Gatherhall","seo_description":"आज की थोड़ी तैयारी पूरे सीज़न को अधिक शांत और व्यवस्थित बना सकती है।","category":"विवाह स्थल मार्गदर्शिका"}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('blog','minimum-guarantee-explained','en','{"title":"Minimum guarantees, without the confusion","summary":"Keep expected attendance, the agreed minimum and actual service clearly separated.","body":"## Three numbers, three purposes\nExpected guests help your team plan. A minimum guarantee is the agreed billing commitment. Actual served guests capture the final attendance when the agreement uses it.\n## Agree before the event\nExplain the rate, guarantee and extra-plate terms in writing. Record any applicable tax and discount without silently changing the agreed menu.\n## Keep a clear final record\nWhen updating actual attendance, compare the final quote to payments already received. Keep the saved statement with the booking.","cta_label":"","seo_title":"Minimum guarantees, without the confusion | Gatherhall","seo_description":"Keep expected attendance, the agreed minimum and actual service clearly separated.","category":"Planning · 4 min read"}'::jsonb,'{"title":"Minimum guarantees, without the confusion","summary":"Keep expected attendance, the agreed minimum and actual service clearly separated.","body":"## Three numbers, three purposes\nExpected guests help your team plan. A minimum guarantee is the agreed billing commitment. Actual served guests capture the final attendance when the agreement uses it.\n## Agree before the event\nExplain the rate, guarantee and extra-plate terms in writing. Record any applicable tax and discount without silently changing the agreed menu.\n## Keep a clear final record\nWhen updating actual attendance, compare the final quote to payments already received. Keep the saved statement with the booking.","cta_label":"","seo_title":"Minimum guarantees, without the confusion | Gatherhall","seo_description":"Keep expected attendance, the agreed minimum and actual service clearly separated.","category":"Planning · 4 min read"}'::jsonb,1,now());
insert into public.cms_entries(kind,slug,locale,draft,published,published_revision,published_at) values('blog','minimum-guarantee-explained','hi','{"title":"न्यूनतम गारंटी को आसानी से समझें","summary":"अनुमानित उपस्थिति, सहमत न्यूनतम संख्या और वास्तविक सेवा का हिसाब अलग रखें।","body":"## तीन संख्याएँ, तीन अलग उद्देश्य\nअनुमानित मेहमान तैयारी में मदद करते हैं। न्यूनतम गारंटी सहमत बिलिंग प्रतिबद्धता है। वास्तविक संख्या आयोजन में सेवा पाए मेहमानों को दर्शाती है।\n## आयोजन से पहले सहमति\nदर, गारंटी और अतिरिक्त प्लेट की शर्तें लिखित रूप में स्पष्ट करें। मेन्यू बदले बिना लागू कर और छूट दर्ज करें।\n## अंतिम रिकॉर्ड स्पष्ट रखें\nवास्तविक उपस्थिति भरते समय अंतिम राशि को प्राप्त भुगतान से मिलाएँ। सहेजा गया विवरण बुकिंग के साथ रखें।","cta_label":"","seo_title":"न्यूनतम गारंटी को आसानी से समझें | Gatherhall","seo_description":"अनुमानित उपस्थिति, सहमत न्यूनतम संख्या और वास्तविक सेवा का हिसाब अलग रखें।","category":"विवाह स्थल मार्गदर्शिका"}'::jsonb,'{"title":"न्यूनतम गारंटी को आसानी से समझें","summary":"अनुमानित उपस्थिति, सहमत न्यूनतम संख्या और वास्तविक सेवा का हिसाब अलग रखें।","body":"## तीन संख्याएँ, तीन अलग उद्देश्य\nअनुमानित मेहमान तैयारी में मदद करते हैं। न्यूनतम गारंटी सहमत बिलिंग प्रतिबद्धता है। वास्तविक संख्या आयोजन में सेवा पाए मेहमानों को दर्शाती है।\n## आयोजन से पहले सहमति\nदर, गारंटी और अतिरिक्त प्लेट की शर्तें लिखित रूप में स्पष्ट करें। मेन्यू बदले बिना लागू कर और छूट दर्ज करें।\n## अंतिम रिकॉर्ड स्पष्ट रखें\nवास्तविक उपस्थिति भरते समय अंतिम राशि को प्राप्त भुगतान से मिलाएँ। सहेजा गया विवरण बुकिंग के साथ रखें।","cta_label":"","seo_title":"न्यूनतम गारंटी को आसानी से समझें | Gatherhall","seo_description":"अनुमानित उपस्थिति, सहमत न्यूनतम संख्या और वास्तविक सेवा का हिसाब अलग रखें।","category":"विवाह स्थल मार्गदर्शिका"}'::jsonb,1,now());
